package cc.ataglace.molebutter.marketplacelotteon.internal.product;
import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;import java.util.concurrent.locks.ReentrantLock;
import org.springframework.beans.factory.annotation.*;import org.springframework.stereotype.Component;import tools.jackson.databind.*;
import cc.ataglace.molebutter.marketplace.api.*;import static cc.ataglace.molebutter.marketplace.api.MarketplaceFailure.Kind.*;
@Component final class LotteonClient {
 record Response(int status,byte[] bytes,String retryAfter) {} interface Transport{Response send(String method,String host,String path,String body);}
 static final String PRODUCT="/v1/openapi/product/v1/";static final String OPEN="https://openapi.lotteon.com",PICK="https://onpick-api.lotteon.com";
 private final String key;final ObjectMapper json;private final Transport transport;private final long spacing;private final ReentrantLock lock=new ReentrantLock(true);
 private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).followRedirects(HttpClient.Redirect.NEVER).build();
 @Autowired LotteonClient(@Value("${marketplace.lotteon.api-key:}")String key,ObjectMapper json){this(key,json,null,1000);}
 LotteonClient(String key,ObjectMapper json,Transport transport,long spacing){this.key=key==null?"":key.trim();this.json=json;this.transport=transport==null?this::http:transport;this.spacing=spacing;}
 String account(){try{return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(("LOTTEON\n"+key).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 JsonNode read(String method,String path,Object body){return parse(request(method,path,body==null?null:json.writeValueAsString(body)));}
 Response request(String method,String path,String body){return request(method,path,body,()->{});}
 Response request(String method,String path,String body,Runnable beforeSend){if(key.isBlank()||key.length()>8192||key.codePoints().anyMatch(c->c<=32||c>=127))throw failure(CONFIGURATION);boolean pick=path.startsWith("/cheetah/econCheetah.ecn?job=");if(!(pick||path.startsWith("/v1/openapi/"))||path.contains("..")||path.contains("#")||path.contains("\r")||path.contains("\n"))throw new IllegalArgumentException("provider path");lock.lock();try{var result=cc.ataglace.molebutter.marketplacelotteon.internal.LotteonCalls.call(key,Duration.ofMillis(spacing),()->{beforeSend.run();return transport.send(method,pick?PICK:OPEN,path,body);});if(result.status()==429){long seconds=60;try{seconds=Math.max(1,Math.min(300,Long.parseLong(result.retryAfter())));}catch(Exception ignored){}cc.ataglace.molebutter.marketplacelotteon.internal.LotteonCalls.block(key,Duration.ofSeconds(seconds));}return result;}finally{lock.unlock();}}
 JsonNode parse(Response r){if(r.status()==401)throw failure(AUTHENTICATION);if(r.status()==403)throw failure(PERMISSION);if(r.status()==429)throw failure(RATE_LIMIT);if(r.status()<200||r.status()>=300)throw failure(REJECTED);try{var node=json.readTree(r.bytes());if(!node.isObject())throw failure(RESPONSE);return node;}catch(MarketplaceFailure e){throw e;}catch(RuntimeException e){throw failure(RESPONSE);}}
 static JsonNode success(JsonNode n){if(!"0000".equals(n.path("returnCode").asString("")))throw failure(REJECTED);return n;}
 private Response http(String method,String host,String path,String body){try{var b=HttpRequest.newBuilder(URI.create(host+path)).timeout(Duration.ofSeconds(25)).header("Authorization","Bearer "+key).header("Accept","application/json").header("Accept-Language","ko").header("X-Timezone","GMT+09:00");if(body!=null)b.header("Content-Type","application/json;charset=UTF-8");b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body));var response=http.send(b.build(),HttpResponse.BodyHandlers.ofInputStream());try(var in=response.body()){var bytes=in.readNBytes(10*1024*1024+1);if(bytes.length>10*1024*1024)throw failure(RESPONSE);return new Response(response.statusCode(),bytes,response.headers().firstValue("Retry-After").orElse("60"));}}catch(HttpTimeoutException e){throw failure(TIMEOUT);}catch(InterruptedException e){Thread.currentThread().interrupt();throw failure(CANCELLED);}catch(java.io.IOException e){throw failure(NETWORK);}}
 static String id(String s){if(s==null||!s.matches("[A-Za-z0-9_-]{1,30}"))throw PartnerFormSupport.invalid("롯데ON 상품·단품 번호를 확인해 주세요.");return s;}
 static String enc(String s){return URLEncoder.encode(s,java.nio.charset.StandardCharsets.UTF_8);}
 static MarketplaceFailure failure(MarketplaceFailure.Kind k){return new MarketplaceFailure(k,"LOTTEON");}
}
